-- Demo data: a global catalog and two stores in different countries, each with
-- five totems.
--
-- LOCAL-0001 keeps the original single-store data exactly: same ids, same USD
-- prices, same deliberately uneven stock (Still water has 1 unit, Iced coffee
-- has 0), so the last-unit race and sold-out paths still work from a fresh seed.
--
-- BR-SP-0001 exists to prove stores are independent: different currency and
-- prices, a smaller product range (no Iced coffee), and its own stock.

TRUNCATE order_items, payments, orders, stock, store_items, totems, stores, items
  RESTART IDENTITY CASCADE;

-- ---------------------------------------------------------------------------
-- Global catalog: what a product is. No price here; prices are per store.
-- ---------------------------------------------------------------------------


-- ---------------------------------------------------------------------------
-- Stores and their totems
-- ---------------------------------------------------------------------------

   'US', 'us-local', 'UTC', 'USD', 'en-US', 0),
  ('a0000000-0000-4000-8000-000000000002', 'BR-SP-0001', 'Snack Bar Paulista',
   'BR', 'br-south-east', 'America/Sao_Paulo', 'BRL', 'pt-BR', 0);


-- ---------------------------------------------------------------------------
-- LOCAL-0001: the original store
-- ---------------------------------------------------------------------------



